const ctx = $('Decode secrets').first().json;
const CLIENT_ID = ctx.client_id;
const INGESTED_AT = new Date().toISOString();
const TF_START = ctx.window_start_date;
const TF_END = ctx.window_end_date;
const num = v => (v === null || v === undefined || v === '' ? null : Number(v));

// /api/campaign-values-reports/ returns a SINGLE object: { data: { attributes: { results: [ {groupings, statistics}, ... ] } } }.
// results includes ALL channels (email + sms + push) — keep them; mart filters channel='email'.
const results = [];
for (const it of $input.all()) {
  const rs = it.json?.data?.attributes?.results;
  if (Array.isArray(rs)) for (const r of rs) results.push(r);
}

return results.filter(r => r?.groupings?.campaign_id).map(r => {
  const g = r.groupings ?? {};
  const s = r.statistics ?? {};
  return { json: {
    client_id: CLIENT_ID,
    ingested_at: INGESTED_AT,
    ingest_source: 'n8n_rolling_35d',
    report_timeframe_start: TF_START,
    report_timeframe_end: TF_END,
    campaign_id: String(g.campaign_id),
    campaign_message_id: g.campaign_message_id ?? null,
    send_channel: g.send_channel ?? null,
    recipients: num(s.recipients),
    delivered: num(s.delivered),
    bounced: num(s.bounced),
    opens: num(s.opens),
    opens_unique: num(s.opens_unique),
    clicks: num(s.clicks),
    clicks_unique: num(s.clicks_unique),
    delivery_rate: num(s.delivery_rate),
    open_rate: num(s.open_rate),
    click_rate: num(s.click_rate),
    conversion_rate: num(s.conversion_rate),
    unsubscribes: num(s.unsubscribes),
    spam_complaints: num(s.spam_complaints),
    conversions: num(s.conversions),
    conversion_value: num(s.conversion_value),
    revenue_per_recipient: num(s.revenue_per_recipient),
    average_order_value: num(s.average_order_value),
    payload_json: JSON.stringify(r)
  }};
});

const ctx = $('Decode secrets').first().json;
const CLIENT_ID = ctx.client_id;
const INGESTED_AT = new Date().toISOString();
const DIM_TYPE = 'channel';
const num = v => (v === null || v === undefined || v === '' ? null : Number(v));

// metric-aggregates: { data: { attributes: { dates: [...], data: [ {dimensions:[...], measurements:{sum_value:[...],count:[...]}} ] } } }
const out = [];
for (const it of $input.all()) {
  const a = it.json?.data?.attributes;
  if (!a) continue;
  const dates = (a.dates || []).map(d => String(d).slice(0, 10));
  for (const row of (a.data || [])) {
    const dv = (row.dimensions && row.dimensions[0] != null) ? String(row.dimensions[0]) : '';
    const sv = row.measurements?.sum_value || [];
    const ct = row.measurements?.count || [];
    for (let i = 0; i < dates.length; i++) {
      out.push({ json: {
        client_id: CLIENT_ID,
        ingested_at: INGESTED_AT,
        ingest_source: 'n8n_conv_rolling_35d',
        metric_date: dates[i],
        dim_type: DIM_TYPE,
        dim_value: dv,
        conversion_value: (sv[i] != null && sv[i] !== '' ? Math.round(Number(sv[i]) * 10000) / 10000 : null),
        conversions: (ct[i] != null ? Math.round(Number(ct[i])) : null),
        payload_json: JSON.stringify({ dim: dv, date: dates[i] })
      }});
    }
  }
}
return out;

