const ctx = $('Decode secrets').first().json;
const CLIENT_ID = ctx.client_id;
const INGESTED_AT = new Date().toISOString();
const num = v => (v === null || v === undefined || v === '' ? null : Number(v));

// flow-series-report: same shape as campaign-series. Zip date_times with each statistic array.
const out = [];
for (const it of $input.all()) {
  const attr = it.json?.data?.attributes;
  if (!attr) continue;
  const dts = (attr.date_times || []).map(d => String(d).slice(0, 10));
  for (const r of (attr.results || [])) {
    const g = r.groupings ?? {};
    const s = r.statistics ?? {};
    if (!g.flow_id) continue;
    const at = (arr, i) => (Array.isArray(arr) ? num(arr[i]) : null);
    for (let i = 0; i < dts.length; i++) {
      out.push({ json: {
        client_id: CLIENT_ID,
        ingested_at: INGESTED_AT,
        ingest_source: 'n8n_series_rolling_35d',
        metric_date: dts[i],
        flow_id: String(g.flow_id),
        flow_message_id: g.flow_message_id ?? null,
        send_channel: g.send_channel ?? null,
        recipients: at(s.recipients, i),
        delivered: at(s.delivered, i),
        bounced: at(s.bounced, i),
        opens: at(s.opens, i),
        opens_unique: at(s.opens_unique, i),
        clicks: at(s.clicks, i),
        clicks_unique: at(s.clicks_unique, i),
        conversions: at(s.conversions, i),
        conversion_value: (function(x){ return (x != null ? Math.round(x * 10000) / 10000 : null); })(at(s.conversion_value, i)),
        unsubscribes: at(s.unsubscribes, i),
        spam_complaints: at(s.spam_complaints, i),
        payload_json: JSON.stringify({ groupings: g, metric_date: dts[i] })
      }});
    }
  }
}
return out;

